function validate([a, b, c]) {
  for (const [name, text] of [['a', a], ['b', b], ['c', c]]) {
    if (typeof text !== 'string' || text.length < 1 || text.length > 100) return `${name} needs 1 to 100 characters.`;
    if (!/^[a-z]+$/.test(text)) return `${name} may contain only lowercase letters.`;
  }
  return null;
}

