function minimumString(a, b, c) {
  const merge = (first, second) => {
    if (first.includes(second)) return first;
    for (let k = Math.min(first.length, second.length); k > 0; k--) {
      if (first.endsWith(second.slice(0, k))) {
        return first + second.slice(k);
      }
    }
    return first + second;
  };

  const orders = [[a, b, c], [a, c, b], [b, a, c], [b, c, a], [c, a, b], [c, b, a]];
  let best = null;
  for (const [x, y, z] of orders) {
    const candidate = merge(merge(x, y), z);
    if (best === null || candidate.length < best.length) {
      best = candidate;
    } else if (candidate.length === best.length && candidate < best) {
      best = candidate;
    }
  }
  return best;
}

