function minimumString(a, b, c) {
  // Try every way to lay the three strings over each other without gaps
  // (one of them starts at 0) and keep the shortest, then smallest, result.
  const words = [a, b, c];
  const perms = [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]];
  let answer = null;
  for (const [i, j, k] of perms) {
    const x = words[i], y = words[j], z = words[k];
    for (let p = 0; p <= x.length; p++) {
      const endY = Math.max(x.length, p + y.length);
      for (let q = 0; q <= endY; q++) {
        const cells = new Array(Math.max(endY, q + z.length)).fill(null);
        let fits = true;
        for (const [word, start] of [[x, 0], [y, p], [z, q]]) {
          for (let t = 0; t < word.length; t++) {
            if (cells[start + t] !== null && cells[start + t] !== word[t]) fits = false;
            cells[start + t] = word[t];
          }
        }
        if (!fits) continue;
        const text = cells.join('');
        if (answer === null || text.length < answer.length || (text.length === answer.length && text < answer)) answer = text;
      }
    }
  }
  return answer;
}

