function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const word = (length, alphabet) => Array.from({ length }, () => 'abcdefghijklmnopqrstuvwxyz'[pick(0, alphabet - 1)]).join('');
  if (size === 'large') {
    const alphabet = [2, 3, 26][pick(0, 2)];
    const base = word(260, alphabet);
    const piece = () => {
      if (rand() < 0.25) return word(pick(60, 100), alphabet);
      const length = pick(40, 100);
      const start = pick(0, base.length - length);
      return base.slice(start, start + length);
    };
    return [piece(), piece(), piece()];
  }
  const alphabet = pick(1, 3);
  return [word(pick(1, 3), alphabet), word(pick(1, 3), alphabet), word(pick(1, 3), alphabet)];
}
